import hashlib
from Crypto.Cipher import AES
from gmssl.sm4 import CryptSM4, SM4_DECRYPT, SM4_ENCRYPT
from binascii import a2b_hex, b2a_hex, hexlify, unhexlify
from IQCommon.const import PWDKEY
from IQCommon.common import AUTH_CODE
def md5salt():
    ascii_code = ord(AUTH_CODE[0:1])
    salt = AUTH_CODE[0:ascii_code % 32]
    seed = (AUTH_CODE + salt)
    m = hashlib.md5()
    m.update(seed.encode())
    return m.hexdigest().lower()
AES_KEY = md5salt()
def get_aes_iv():
    aes_iv = ''
    if (len(AES_KEY) != 32):
        aes_iv = 'abcdefghijklmnop'
    else:
        for i in range(len(AES_KEY)):
            if (i % 2 == 0):
                aes_iv += AES_KEY[i]
            continue
    return aes_iv
AES_IV = get_aes_iv()
def aes_encrypt(message, aes_key=None, aes_iv=None, return_str=False):
    if (aes_key is not None and aes_iv is not None and isinstance(aes_key, str)):
        aes_key = aes_key.encode()
    if isinstance(aes_iv, str):
        aes_iv = aes_iv.encode()
    cipher = AES.new(aes_key, AES.MODE_CBC, aes_iv)
    cipher = AES.new(AES_KEY.encode(), AES.MODE_CBC, AES_IV.encode())
    length = 32
    message = message.encode('utf-8')
    count = len(message)
    add = (length - count % length)
    padded_message = (message + b' ' * add)
    encrypt_message = cipher.encrypt(padded_message)
    if return_str:
        return b2a_hex(encrypt_message).decode()
    else:
        return b2a_hex(encrypt_message)
def aes_decrypt(message, aes_key=None, aes_iv=None):
    if (aes_key is not None and aes_iv is not None and isinstance(aes_key, str)):
        aes_key = aes_key.encode()
    if isinstance(aes_iv, str):
        aes_iv = aes_iv.encode()
    cipher = AES.new(aes_key, AES.MODE_CBC, aes_iv)
    cipher = AES.new(AES_KEY.encode(), AES.MODE_CBC, AES_IV.encode())
    decrypt_message = cipher.decrypt(a2b_hex(message)).rstrip(b'\x00').rstrip(b' ')
    return decrypt_message.decode('utf-8', 'ignore')
def encrypt(message):
    message_bytes = bytearray(str(message).encode('utf8'))
    byte_count = len(message_bytes)
    encrypted_bytes = bytearray(byte_count * 2)
    idx = 0
    for i in range(0, byte_count):
        xor_result = (message_bytes[i] ^ PWDKEY)
        character1 = (xor_result % 16 + 65)
        character2 = (xor_result // 16 + 65)
        encrypted_bytes[idx] = character1
        encrypted_bytes[idx + 1] = character2
        idx += 2
    else:
        return encrypted_bytes.decode('utf8')
def decrypt(message):
    encrypted_bytes = bytearray(str(message).encode('utf8'))
    byte_count = len(encrypted_bytes)
    if (byte_count % 2 != 0):
        return ''
    else:
        byte_count = (byte_count // 2)
        decrypted_bytes = bytearray(byte_count)
        idx = 0
        for i in range(0, byte_count):
            character1 = encrypted_bytes[idx]
            character2 = encrypted_bytes[idx + 1]
            idx += 2
            character1 -= 65
            character2 -= 65
            xor_result = (character2 * 16 + character1)
            xor_result ^= PWDKEY
            decrypted_bytes[i] = xor_result
        else:
            return decrypted_bytes.decode('utf8', 'ignore')
def sm4_decrypt(input_data: str, external_flag=False) -> str:
    if external_flag:
        key = b'887dcnEd5123666\x00'
    else:
        key = b'887dcnEd5123667\x00'
    crypt_sm4 = CryptSM4()
    crypt_sm4.set_key(key, SM4_DECRYPT)
    b_output_data = unhexlify(input_data.encode())
    dec_data = crypt_sm4.crypt_ecb(b_output_data).decode()
    return dec_data
def sm4_encrypt(input_data: str, external_flag=False) -> str:
    if external_flag:
        key = b'887dcnEd5123666\x00'
    else:
        key = b'887dcnEd5123667\x00'
    crypt_sm4 = CryptSM4()
    crypt_sm4.set_key(key, SM4_ENCRYPT)
    output_data = crypt_sm4.crypt_ecb(input_data.encode())
    enc_dat = hexlify(output_data).decode()
    return enc_dat
